 * This program is free software, you can redistribute it and/or modify it under the terms and conditions of
 * CANN Open Software License Agreement Version 2.0 (the "License").
 * Please refer to the License for details. You may not use this file except in compliance with the License.
 * THIS SOFTWARE IS PROVIDED ON AN "AS IS" BASIS, WITHOUT WARRANTIES OF ANY KIND, EITHER EXPRESS OR IMPLIED,
 * INCLUDING BUT NOT LIMITED TO NON-INFRINGEMENT, MERCHANTABILITY, OR FITNESS FOR A PARTICULAR PURPOSE.
 * See LICENSE in the root of the software repository for the full text of the License.
 */

#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelAdd {
public:
    __aicore__ inline KernelAdd() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR z,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength,
                                float alpha)
    {
        int64_t blockIdx = static_cast<int64_t>(AscendC::GetBlockIdx());

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
            zGm.SetGlobalBuffer((__gm__ T *)z + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
            zGm.SetGlobalBuffer((__gm__ T *)z + offset, tailLength);
        }

        this->tileLength = tileLength;
        this->alpha = alpha;

        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(inQueueY, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueueZ, BUFFER_NUM, tileLength * sizeof(T));

        if constexpr (sizeof(T) != sizeof(float)) {
            pipe.InitBuffer(tmpBufX, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBufY, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBufZ, tileLength * sizeof(float));
            pipe.InitBuffer(tmpBufAlpha, tileLength * sizeof(float));
        }
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        int64_t alignNum = 32 / static_cast<int64_t>(sizeof(T));
        int64_t alignedTailLen = ((tailTileLength + alignNum - 1) / alignNum) * alignNum;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tileNum > 0) {
            CopyIn(tileNum - 1, alignedTailLen);
            Compute(tileNum - 1, alignedTailLen);
            CopyOut(tileNum - 1, alignedTailLen);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        AscendC::LocalTensor<T> yLocal = inQueueY.AllocTensor<T>();

        int64_t offset = progress * this->tileLength;

        AscendC::DataCopyExtParams copyParamsX{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParamsX{false, 0, 0, 0};
        AscendC::DataCopyPad(xLocal, xGm[offset], copyParamsX, padParamsX);

        AscendC::DataCopyExtParams copyParamsY{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParamsY{false, 0, 0, 0};
        AscendC::DataCopyPad(yLocal, yGm[offset], copyParamsY, padParamsY);

        inQueueX.EnQue(xLocal);
        inQueueY.EnQue(yLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
        AscendC::LocalTensor<T> yLocal = inQueueY.DeQue<T>();
        AscendC::LocalTensor<T> zLocal = outQueueZ.AllocTensor<T>();

        if constexpr (sizeof(T) == sizeof(float)) {
            // float32: direct compute
            AscendC::LocalTensor<float> tmpLocal = tmpBufAlpha.Get<float>();
            AscendC::Muls(tmpLocal, yLocal, this->alpha, curTileLength);
            AscendC::Add(zLocal, xLocal, tmpLocal, curTileLength);
        } else {
            // fp16/bf16: cast to fp32, compute, cast back
            AscendC::LocalTensor<float> xFp32 = tmpBufX.Get<float>();
            AscendC::LocalTensor<float> yFp32 = tmpBufY.Get<float>();
            AscendC::LocalTensor<float> zFp32 = tmpBufZ.Get<float>();
            AscendC::LocalTensor<float> tmpFp32 = tmpBufAlpha.Get<float>();

            AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(yFp32, yLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Muls(tmpFp32, yFp32, this->alpha, curTileLength);
            AscendC::Add(zFp32, xFp32, tmpFp32, curTileLength);
            AscendC::Cast(zLocal, zFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
        }

        inQueueX.FreeTensor(xLocal);
        inQueueY.FreeTensor(yLocal);
        outQueueZ.EnQue(zLocal);
    }

    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> zLocal = outQueueZ.DeQue<T>();

        int64_t offset = progress * this->tileLength;
        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPad(zGm[offset], zLocal, copyParams);

        outQueueZ.FreeTensor(zLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueY;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueZ;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBufX;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBufY;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBufZ;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBufAlpha;
    AscendC::GlobalTensor<T> xGm;
    AscendC::GlobalTensor<T> yGm;
    AscendC::GlobalTensor<T> zGm;
    int64_t blockLength;
    int64_t tileLength;
    float alpha;
};

extern "C" __global__ __aicore__ void add(GM_ADDR x, GM_ADDR y, GM_ADDR z,
                                            int64_t formerNum, int64_t formerLength,
                                            int64_t tailLength, int64_t tileLength,
                                            int64_t dtypeSize, float alpha)
{
    if (dtypeSize == 2) {
        KernelAdd<half> op;
        op.Init(x, y, z, formerNum, formerLength, tailLength, tileLength, alpha);
        op.Process();
    } else {
        KernelAdd<float> op;
        op.Init(x, y, z, formerNum, formerLength, tailLength, tileLength, alpha);
        op.Process();
    }
}
