#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_add.h"

namespace ascend_kernel {

constexpr int64_t CACHE_LINE_BYTE_LENGTH = 512;

at::Tensor add(const at::Tensor &self, const at::Tensor &other, float alpha)
{
    // ---- input validation ----
    TORCH_CHECK(self.scalar_type() == at::kHalf || self.scalar_type() == at::kFloat || self.scalar_type() == at::kBFloat16,
                "add: only float16, bfloat16 and float32 are supported, got ", self.scalar_type());
    TORCH_CHECK(other.scalar_type() == self.scalar_type(),
                "add: other dtype must match self dtype");

    // Broadcasting: compute output shape
    at::Tensor self_bc = self;
    at::Tensor other_bc = other;
    if (self.sizes() != other.sizes()) {
        self_bc = self.broadcast_to(at::infer_size(self.sizes(), other.sizes()));
        other_bc = other.broadcast_to(at::infer_size(self.sizes(), other.sizes()));
    }

    at::Tensor output = at::empty_like(self_bc);

    int64_t totalLength = self_bc.numel();
    if (totalLength == 0) {
        return output;
    }

    int64_t dtypeSize = self_bc.element_size();

    // ---- get hardware params ----
    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
    uint64_t ubSize;
    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);

    // ---- Block level tiling (inter-core split, Cache Line aligned) ----
    int64_t totalLengthCore = (totalLength + coreNum - 1) / coreNum;
    int64_t totalLengthCoreAlign = (totalLengthCore * dtypeSize + CACHE_LINE_BYTE_LENGTH - 1)
                                    / CACHE_LINE_BYTE_LENGTH * CACHE_LINE_BYTE_LENGTH / dtypeSize;

    int64_t usedCoreNum = (totalLength + totalLengthCoreAlign - 1) / totalLengthCoreAlign;
    int64_t formerNum = usedCoreNum - 1;
    int64_t formerLength = totalLengthCoreAlign;
    int64_t tailLength = totalLength - formerNum * formerLength;

    // ---- UB level tiling (intra-core split) ----
    // bufferCoefficient from UB allocation table:
    // float32 dual-input: 32, float16/bf16 dual-input: 24
    int64_t bufferCoefficient = (dtypeSize == 4) ? 32 : 24;
    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
    int64_t alignElements = 32 / dtypeSize;
    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
    if (tileLength == 0) {
        tileLength = alignElements;
    }

    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);

    // All params must be left values
    int64_t formerNumL = formerNum;
    int64_t formerLengthL = formerLength;
    int64_t tailLengthL = tailLength;
    int64_t tileLengthL = tileLength;
    int64_t dtypeSizeL = dtypeSize;
    float alphaL = alpha;

    EXEC_KERNEL_CMD(add, blockDim,
                    self_bc, other_bc, output,
                    formerNumL, formerLengthL, tailLengthL, tileLengthL, dtypeSizeL, alphaL);

    return output;
}

}  // namespace ascend_kernel
