#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2;

template <typename T>
class KernelAdd {
public:
    __aicore__ inline KernelAdd() {}

    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR z,
                                int64_t formerNum, int64_t formerLength,
                                int64_t tailLength, int64_t tileLength,
                                float alpha)
    {
        int64_t blockIdx = static_cast<int64_t>(AscendC::GetBlockIdx());

        if (blockIdx < formerNum) {
            this->blockLength = formerLength;
            int64_t offset = formerLength * blockIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
            zGm.SetGlobalBuffer((__gm__ T *)z + offset, formerLength);
        } else {
            this->blockLength = tailLength;
            int64_t tailIdx = blockIdx - formerNum;
            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
            zGm.SetGlobalBuffer((__gm__ T *)z + offset, tailLength);
        }

        this->tileLength = tileLength;
        this->alpha = alpha;

        pipe.InitBuffer(inQueueX, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(inQueueY, BUFFER_NUM, tileLength * sizeof(T));
        pipe.InitBuffer(outQueueZ, BUFFER_NUM, tileLength * sizeof(T));
    }

    __aicore__ inline void Process()
    {
        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;

        for (int64_t i = 0; i < tileNum - 1; ++i) {
            CopyIn(i, this->tileLength);
            Compute(i, this->tileLength);
            CopyOut(i, this->tileLength);
        }
        if (tileNum > 0) {
            CopyIn(tileNum - 1, tailTileLength);
            Compute(tileNum - 1, tailTileLength);
            CopyOut(tileNum - 1, tailTileLength);
        }
    }

private:
    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
        AscendC::LocalTensor<T> yLocal = inQueueY.AllocTensor<T>();

        int64_t offset = progress * this->tileLength;

        AscendC::DataCopyExtParams copyParamsX{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParamsX{false, 0, 0, 0};
        AscendC::DataCopyPad(xLocal, xGm[offset], copyParamsX, padParamsX);

        AscendC::DataCopyExtParams copyParamsY{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
        AscendC::DataCopyPadExtParams<T> padParamsY{false, 0, 0, 0};
        AscendC::DataCopyPad(yLocal, yGm[offset], copyParamsY, padParamsY);

        inQueueX.EnQue(xLocal);
        inQueueY.EnQue(yLocal);
    }

    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
    {
        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
        AscendC::LocalTensor<T> yLocal = inQueueY.DeQue<T>();
        AscendC::LocalTensor<T> zLocal = outQueueZ.AllocTensor<T>();

        if constexpr (sizeof(T) == sizeof(float)) {
            // float32: direct compute
            AscendC::Muls(zLocal, yLocal, this->alpha, curTileLength);
            AscendC::Add(zLocal, xLocal, zLocal, curTileLength);
        } else {
            // fp16/bf16: use ReinterpretCast to reuse buffers for fp32 compute
            AscendC::LocalTensor<float> xFp32 = xLocal.ReinterpretCast<float>();
            AscendC::LocalTensor<float> yFp32 = yLocal.ReinterpretCast<float>();
            AscendC::LocalTensor<float> zFp32 = zLocal.ReinterpretCast<float>();

            // Cast fp16 -> fp32 (count for fp32 is half of fp16 count)
            int64_t fp32Count = (curTileLength + 1) / 2;
            AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
            AscendC::Cast(yFp32, yLocal, AscendC::RoundMode::CAST_NONE, curTileLength);

            // FP32 compute
            AscendC::Muls(yFp32, yFp32, this->alpha, curTileLength);
            AscendC::Add(zFp32, xFp32, yFp32, curTileLength);

            // Cast fp32 -> fp16
            AscendC::Cast(zLocal, zFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
        }

