69	    // For fp32: total UB = 6 * elemBufBytes = 6 * align32(tileLength * 4)
70	    // Use conservative coefficient to ensure we don't exceed UB
71	    int64_t bufferCoefficient = (dtypeSize == 4) ? 24 : 40;
72	    int64_t maxTileElements = ubSizeLimit / bufferCoefficient;
73	    int64_t alignElements = 32 / dtypeSize;
74	    int64_t tileLength = (maxTileElements / alignElements) * alignElements;
75	    if (tileLength == 0) {
76	        tileLength = alignElements;
77	    }
78	
79	    uint32_t blockDim = static_cast<uint32_t>(usedCoreNum);
80	
81	    // All params must be left values
82	    int64_t formerNumL = formerNum;
83	    int64_t formerLengthL = formerLength;
84	    int64_t tailLengthL = tailLength;
85	    int64_t tileLengthL = tileLength;
86	    int64_t dtypeSizeL = dtypeSize;
87	    float alphaL = alpha;
88	
89	    EXEC_KERNEL_CMD(add, blockDim,
90	                    self_bc, other_bc, output,
91	                    formerNumL, formerLengthL, tailLengthL, tileLengthL, dtypeSizeL, alphaL);
92	
93	    return output;
94	}
