12	
13	constexpr int32_t BUFFER_NUM = 2;
14	
15	template <typename T>
16	class KernelAdd {
17	public:
18	    __aicore__ inline KernelAdd() {}
19	
20	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR z,
21	                                int64_t formerNum, int64_t formerLength,
22	                                int64_t tailLength, int64_t tileLength,
23	                                float alpha)
24	    {
25	        int64_t blockIdx = static_cast<int64_t>(AscendC::GetBlockIdx());
26	
27	        if (blockIdx < formerNum) {
28	            this->blockLength = formerLength;
29	            int64_t offset = formerLength * blockIdx;
30	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, formerLength);
31	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, formerLength);
32	            zGm.SetGlobalBuffer((__gm__ T *)z + offset, formerLength);
33	        } else {
34	            this->blockLength = tailLength;
35	            int64_t tailIdx = blockIdx - formerNum;
36	            int64_t offset = formerLength * formerNum + tailLength * tailIdx;
37	            xGm.SetGlobalBuffer((__gm__ T *)x + offset, tailLength);
38	            yGm.SetGlobalBuffer((__gm__ T *)y + offset, tailLength);
39	            zGm.SetGlobalBuffer((__gm__ T *)z + offset, tailLength);
40	        }
41	
42	        this->tileLength = tileLength;
43	        this->alpha = alpha;
44	
45	        // Buffer size in bytes - must be 32B aligned for UB
46	        int64_t dtypeSize = static_cast<int64_t>(sizeof(T));
47	        int64_t alignBytes = 32;
48	        int64_t elemBufBytes = ((tileLength * dtypeSize + alignBytes - 1) / alignBytes) * alignBytes;
49	
50	        pipe.InitBuffer(inQueueX, BUFFER_NUM, elemBufBytes);
51	        pipe.InitBuffer(inQueueY, BUFFER_NUM, elemBufBytes);
52	        pipe.InitBuffer(outQueueZ, BUFFER_NUM, elemBufBytes);
53	
54	        // For fp16/bf16: allocate fp32 temp buffers (each is tileLength * 4 bytes, aligned)
55	        if constexpr (sizeof(T) != sizeof(float)) {
56	            int64_t fp32BufBytes = ((tileLength * sizeof(float) + alignBytes - 1) / alignBytes) * alignBytes;
57	            pipe.InitBuffer(tmpBufX, fp32BufBytes);
58	            pipe.InitBuffer(tmpBufY, fp32BufBytes);
59	            pipe.InitBuffer(tmpBufZ, fp32BufBytes);
60	            pipe.InitBuffer(tmpBufW, fp32BufBytes);
61	        }
62	    }
63	
64	    __aicore__ inline void Process()
65	    {
66	        int64_t tileNum = (this->blockLength + this->tileLength - 1) / this->tileLength;
67	        int64_t tailTileLength = this->blockLength - (tileNum - 1) * this->tileLength;
68	
69	        for (int64_t i = 0; i < tileNum - 1; ++i) {
70	            CopyIn(i, this->tileLength);
71	            Compute(i, this->tileLength);
72	            CopyOut(i, this->tileLength);
73	        }
74	        if (tileNum > 0) {
75	            CopyIn(tileNum - 1, tailTileLength);
76	            Compute(tileNum - 1, tailTileLength);
77	            CopyOut(tileNum - 1, tailTileLength);
78	        }
79	    }
80	
81	private:
82	    __aicore__ inline void CopyIn(int64_t progress, int64_t curTileLength)
83	    {
84	        AscendC::LocalTensor<T> xLocal = inQueueX.AllocTensor<T>();
85	        AscendC::LocalTensor<T> yLocal = inQueueY.AllocTensor<T>();
86	
87	        int64_t offset = progress * this->tileLength;
88	
89	        AscendC::DataCopyExtParams copyParamsX{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
90	        AscendC::DataCopyPadExtParams<T> padParamsX{false, 0, 0, 0};
91	        AscendC::DataCopyPad(xLocal, xGm[offset], copyParamsX, padParamsX);
92	
93	        AscendC::DataCopyExtParams copyParamsY{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
94	        AscendC::DataCopyPadExtParams<T> padParamsY{false, 0, 0, 0};
95	        AscendC::DataCopyPad(yLocal, yGm[offset], copyParamsY, padParamsY);
96	
97	        inQueueX.EnQue(xLocal);
98	        inQueueY.EnQue(yLocal);
99	    }
100	
101	    __aicore__ inline void Compute(int64_t progress, int64_t curTileLength)
102	    {
103	        AscendC::LocalTensor<T> xLocal = inQueueX.DeQue<T>();
104	        AscendC::LocalTensor<T> yLocal = inQueueY.DeQue<T>();
105	        AscendC::LocalTensor<T> zLocal = outQueueZ.AllocTensor<T>();
106	
107	        if constexpr (sizeof(T) == sizeof(float)) {
108	            // float32: direct compute
109	            AscendC::Muls(zLocal, yLocal, this->alpha, curTileLength);
110	            AscendC::Add(zLocal, xLocal, zLocal, curTileLength);
111	        } else {
112	            // fp16/bf16: cast to fp32, compute, cast back
113	            AscendC::LocalTensor<float> xFp32 = tmpBufX.Get<float>();
114	            AscendC::LocalTensor<float> yFp32 = tmpBufY.Get<float>();
115	            AscendC::LocalTensor<float> zFp32 = tmpBufZ.Get<float>();
116	            AscendC::LocalTensor<float> wFp32 = tmpBufW.Get<float>();
117	
118	            AscendC::Cast(xFp32, xLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
119	            AscendC::Cast(yFp32, yLocal, AscendC::RoundMode::CAST_NONE, curTileLength);
120	            AscendC::Muls(wFp32, yFp32, this->alpha, curTileLength);
121	            AscendC::Add(zFp32, xFp32, wFp32, curTileLength);
122	            AscendC::Cast(zLocal, zFp32, AscendC::RoundMode::CAST_ROUND, curTileLength);
123	        }
124	
125	        inQueueX.FreeTensor(xLocal);
126	        inQueueY.FreeTensor(yLocal);
127	        outQueueZ.EnQue(zLocal);
128	    }
129	
130	    __aicore__ inline void CopyOut(int64_t progress, int64_t curTileLength)
131	    {
132	        AscendC::LocalTensor<T> zLocal = outQueueZ.DeQue<T>();
133	
134	        int64_t offset = progress * this->tileLength;
135	        AscendC::DataCopyExtParams copyParams{1, static_cast<uint32_t>(curTileLength * sizeof(T)), 0, 0, 0};
136	        AscendC::DataCopyPad(zGm[offset], zLocal, copyParams);
137	
138	        outQueueZ.FreeTensor(zLocal);
139	    }
140	
141	private:
142	    AscendC::TPipe pipe;
143	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueX;
144	    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueueY;
145	    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueueZ;
146	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBufX;
147	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBufY;
148	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBufZ;
149	    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBufW;
150	    AscendC::GlobalTensor<T> xGm;
151	    AscendC::GlobalTensor<T> yGm;
152	    AscendC::GlobalTensor<T> zGm;
153	    int64_t blockLength;
154	    int64_t tileLength;
155	    float alpha;
156	};
157	
158	extern "C" __global__ __aicore__ void add(GM_ADDR x, GM_ADDR y, GM_ADDR z,
159	                                            int64_t formerNum, int64_t formerLength,
160	                                            int64_t tailLength, int64_t tileLength,
161	                                            int64_t dtypeSize, float alpha)
162	{
163	    if (dtypeSize == 2) {
164	        KernelAdd<half> op;
165	        op.Init(x, y, z, formerNum, formerLength, tailLength, tileLength, alpha);
166	        op.Process();
167	    } else {
168	        KernelAdd<float> op;
169	        op.Init(x, y, z, formerNum, formerLength, tailLength, tileLength, alpha);
170	        op.Process();
171	    }
172	}
