18	
19	at::Tensor add(const at::Tensor &self, const at::Tensor &other, double alpha)
20	{
21	    // ---- input validation ----
22	    TORCH_CHECK(self.scalar_type() == at::kHalf || self.scalar_type() == at::kFloat || self.scalar_type() == at::kBFloat16,
23	                "add: only float16, bfloat16 and float32 are supported, got ", self.scalar_type());
24	    TORCH_CHECK(other.scalar_type() == self.scalar_type(),
25	                "add: other dtype must match self dtype");
26	
27	    // Broadcasting: compute output shape and make contiguous
28	    at::Tensor self_bc = self;
29	    at::Tensor other_bc = other;
30	    if (self.sizes() != other.sizes()) {
31	        auto out_shape = at::infer_size(self.sizes(), other.sizes());
32	        self_bc = self.broadcast_to(out_shape).contiguous();
33	        other_bc = other.broadcast_to(out_shape).contiguous();
34	    } else {
35	        self_bc = self.contiguous();
36	        other_bc = other.contiguous();
37	    }
38	
39	    at::Tensor output = at::empty_like(self_bc);
40	
41	    int64_t totalLength = self_bc.numel();
42	    if (totalLength == 0) {
43	        return output;
44	    }
45	
46	    // dtypeSize encoding for kernel:
47	    //   1 = half (float16)
48	    //   2 = bfloat16
49	    //   4 = float32
50	    int64_t dtypeSize;
51	    if (self_bc.scalar_type() == at::kHalf) {
52	        dtypeSize = 1;
53	    } else if (self_bc.scalar_type() == at::kBFloat16) {
54	        dtypeSize = 2;
55	    } else {
56	        dtypeSize = 4;
57	    }
58	
59	    // ---- get hardware params ----
60	    auto ascendc_platform = platform_ascendc::PlatformAscendCManager::GetInstance();
61	    int64_t coreNum = static_cast<int64_t>(ascendc_platform->GetCoreNumAiv());
62	    uint64_t ubSize;
63	    ascendc_platform->GetCoreMemSize(platform_ascendc::CoreMemType::UB, ubSize);
64	    int64_t ubSizeLimit = static_cast<int64_t>(ubSize);
65	
66	    // ---- Block level tiling (inter-core split, Cache Line aligned) ----
